"""Orchestrator — 本地任务编排引擎。

将 Decomposer → Executor → Auditor → Settlement → Checkpoint 串联为
完整的编排流水线。

用法:
    orchestrator = Orchestrator(app)
    result = orchestrator.run(message)
    # result 是最终回复字符串
"""
import logging
import uuid

from agent_runtime.orchestration.decomposer import TaskDecomposer, TaskPlan
from agent_runtime.orchestration.executor import SubTaskExecutor
from agent_runtime.orchestration.auditor import SubTaskAuditor
from agent_runtime.orchestration.settlement import Settlement
from agent_runtime.orchestration.checkpoint import CheckpointManager

logger = logging.getLogger("agent.orchestration")

# 最大重试次数
_MAX_RETRIES = 2


class Orchestrator:
    """本地任务编排引擎。

    流水线：
    1. 复杂度评估 → 简单任务直接返回 None（由 process_message 处理）
    2. 任务拆解 → TaskPlan
    3. 按依赖顺序执行子任务 → Executor（新鲜上下文）
    4. 每个子任务执行后 → Auditor 验证
    5. 验证失败 → 重试（最多 _MAX_RETRIES 次）
    6. 所有子任务完成 → Settlement 汇总
    7. 全程 → Checkpoint 持久化
    """

    def __init__(self, app):
        self.app = app
        self.decomposer = TaskDecomposer(
            app.llm, app.skills, app.tools)
        self.executor = SubTaskExecutor(app)
        self.auditor = SubTaskAuditor(app.llm)
        self.settlement = Settlement(app)
        self.checkpoint = CheckpointManager(app.db)

    def run(self, message):
        """执行任务编排。

        参数:
            message: 用户消息

        返回:
            str: 最终回复（如果任务简单返回 None，由调用方走 process_message）
        """
        # 0. 先走 IntentRouter，高置信度 → 简单任务，跳过编排
        if hasattr(self.app, 'router'):
            route = self.app.router.route(message)
            if route.get('confidence', 0) >= 0.7:
                logger.info('IntentRouter 高置信度(%.2f) intent=%s，跳过编排',
                            route['confidence'], route.get('intent'))
                return None

        # 1. 用 FAST_MODEL 评估复杂度（不用主模型）
        is_complex, reason, steps = self.decomposer.assess_complexity(message)
        if not is_complex:
            logger.info('任务评估为简单（%s），跳过编排', reason)
            return None

        logger.info('任务评估为复杂（%s，估计 %d 步），启动编排',
                    reason, steps)

        # 2. 任务拆解
        plan = self.decomposer.decompose(message)
        if not plan or not plan.subtasks:
            logger.warning('任务拆解失败，回退到 process_message')
            return None

        # 创建主任务记录
        self.app.db.create_task(plan.plan_id, message)

        # 3. 按依赖顺序执行子任务
        self._execute_plan(plan)

        # 4. 结算
        result = self.settlement.settle(plan)

        # 5. 清理检查点（任务已完成）
        self.checkpoint.delete(plan.plan_id)

        return result.final_reply

    def _execute_plan(self, plan):
        """按依赖顺序执行子任务计划。"""
        max_rounds = len(plan.subtasks) * (_MAX_RETRIES + 1)
        round_count = 0

        while not plan.is_complete() and round_count < max_rounds:
            round_count += 1
            ready = plan.get_ready_subtasks()

            if not ready:
                # 没有可执行的子任务，可能有循环依赖
                logger.warning('无可执行子任务（可能存在循环依赖）')
                for t in plan.subtasks:
                    if t.status == 'pending':
                        t.status = 'failed'
                        t.result = '依赖未满足'
                break

            for subtask in ready:
                self._execute_with_retry(subtask, plan)
                # 每个子任务执行后保存检查点
                self.checkpoint.save(plan)

    def _execute_with_retry(self, subtask, plan):
        """执行子任务，失败时重试。"""
        for attempt in range(_MAX_RETRIES + 1):
            success, result, evidence = self.executor.execute(subtask, plan)

            if success:
                # 审计验证
                audit = self.auditor.audit(subtask)
                if audit.passed:
                    return  # 成功且通过审计

                if audit.should_retry and attempt < _MAX_RETRIES:
                    logger.info('子任务 %s 审计未通过（第 %d 次重试）: %s',
                                subtask.id, attempt + 1, audit.issues)
                    subtask.status = 'pending'
                    continue
                else:
                    # 审计未通过但不重试
                    logger.warning('子任务 %s 审计未通过（不再重试）: %s',
                                   subtask.id, audit.issues)
                    return

            else:
                if attempt < _MAX_RETRIES:
                    logger.info('子任务 %s 执行失败（第 %d 次重试）',
                                subtask.id, attempt + 1)
                    subtask.status = 'pending'
                else:
                    logger.error('子任务 %s 执行失败（已用尽重试）',
                                 subtask.id)
